import {booked, payments} from './payments';
export {wholeCheckout,reclaimReservation} from './settlement-recovery';
export function splitCheckout(line: string, parts: number[]) {
  const payment = payments.find((candidate) => candidate.id === line);
  const prefix = `payment:${line}:`;
  const hasExistingAllocation = [...booked.keys()].some((key) =>
    key === `payment:${line}` || key.startsWith(prefix),
  );

  if (hasExistingAllocation) return { status: 'already-booked' as const };
  if (!payment || !payment.posted || payment.rejectedAt) {
    return { status: 'invalid-payment' as const };
  }
  if (
    parts.length < 2 ||
    parts.some((cents) => !Number.isSafeInteger(cents) || cents < 0) ||
    parts.reduce((total, cents) => total + cents, 0) !== payment.cents
  ) {
    return { status: 'invalid-allocation' as const };
  }

  // Validate the complete split before writing so a rejected split cannot
  // leave a partial reservation behind.
  parts.forEach((cents, index) => {
    booked.set(`${prefix}part:${index}`, cents);
  });
  return { status: 'booked' as const };
}

